#include <stdio.h>
#include <pthread.h>

static int x = 1;

static void *f(void *a)
{
    (void)a;
    x = 2;
    return NULL;
}

int main(void)
{
    pthread_t t;

    pthread_create(&t, NULL, f, NULL);
    pthread_join(t, NULL);
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

static void *square(void *a)
{
    int *r = malloc(sizeof *r);

    *r = *(int *)a * *(int *)a;
    return r;
}

int main(void)
{
    pthread_t t;
    int n = 7;
    void *ret;

    pthread_create(&t, NULL, square, &n);
    pthread_join(t, &ret);
    printf("%d\n", *(int *)ret);
    free(ret);
    return 0;
}
